 style.textContent+=`.location-navigation-bar{grid-template-rows:auto minmax(28px,1fr) auto}.location-mode-toolbar{display:flex;align-items:center;gap:16px;width:100%;font:14px -apple-system,BlinkMacSystemFont,sans-serif;color:#e6dcea}.location-mode-toolbar>strong{white-space:nowrap}.location-mode-toolbar>.location-mode-categories{flex:1;min-width:0}.location-mode-toolbar>button{border:0;border-radius:9px;background:#ffffff14;color:inherit;padding:6px 12px;font:18px system-ui;cursor:pointer}.location-mode-categories{display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;min-height:26px;align-items:center}.location-mode-categories button{flex:none;border:0;border-radius:8px;padding:4px 10px;background:#e8e8ed;color:#696973;font-size:12px;white-space:nowrap}.location-mode-categories button[aria-pressed=true]{background:#e2edff;color:#007aff}.location-mode-categories small{font-size:10px;margin-left:5px;opacity:.65}@media(max-width:700px){.location-mode-categories button{font-size:11px;padding:3px 8px}}`;
 const workspaceBody=root.querySelector('.scene-workspace-body');bar.hidden=true;visual.hidden=true;await animateSurface(workspaceBody,false,{duration:240,distance:24});root.append(style);root.dataset.locationMode='true';bar.hidden=false;visual.hidden=false;bar.style.opacity='0';const toolbar=doc.createElement('header');toolbar.className='location-mode-toolbar';root.append(toolbar);const toolbarDock=dockSceneToolbar(doc,toolbar);await toolbarDock.ready;let disposed=false,notice='',refreshRevision=0,category='全部',lastScope=state.scopeId,showEffects=false,previewMessage=null;
