  createImage(){return doc.createElement('img');},
  onPending(){previewMessage?.remove();previewMessage=null;visual.dataset.backgroundState='loading';},
  onCommit(image,{place}){image.alt=navigationLabel(place);visual.replaceChildren(image);previewMessage=null;visual.dataset.backgroundAvailable='true';visual.dataset.backgroundState='ready';visual.dataset.backgroundLocationId=place.id;},
  onFallback({image,detail:{place},missing}){previewMessage?.remove();const message=doc.createElement('div');message.className='location-mode-placeholder';const title=doc.createElement('h2'),text=doc.createElement('p');title.textContent=navigationLabel(place);text.textContent=missing?'这个地点的背景图片待补全':'这个地点的背景暂时无法加载';message.append(title,text);visual.append(message);previewMessage=message;visual.dataset.backgroundAvailable=String(Boolean(image));visual.dataset.backgroundState=image?'fallback':'empty';},
